std::string archive_key(std::string_view value) {
    // The target's Win32 path parser treats both separators as path
    // boundaries. Normalize before using the POSIX host path type so a
    // registered component such as "Archive\data01000.arc" maps to the same
    // archive as its indexed filename "data01000.arc".
    const std::string normalized = normalize_resource_name(
        std::string(value));
    std::string key = std::filesystem::path(normalized)
                          .filename()
                          .string();
    if (key.ends_with(".arc")) {
        key.resize(key.size() - 4);
    }
    return key;
}
